L6_1.m_Talk_VTN = L7_1
L7_1 = "\232\175\157\232\175\180\239\188\140\232\191\153\229\165\189\229\131\143\230\152\175\230\136\145\231\172\172\228\184\128\230\172\161\229\145\138\232\175\137\228\189\160\230\136\145\231\154\132\229\144\141\229\173\151\227\128\130"
